import numpy as np
from itertools import combinations_with_replacement as cwr
feats=[];names=[]
for d in range(0,4):
    for combo in cwr(range(3),d):
        f=np.ones_like(t); nm=''
        for i in combo: f=f*[t,x,v][i]; nm+=['t','x','v'][i]
        feats.append(f); names.append(nm or '1')
X=np.column_stack(feats)
c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
print('NMSE cubic',np.mean((X@c-dv_dt)**2)/np.var(dv_dt))
for n,ci in zip(names,c):
    if abs(ci)>1e-3: print(n,round(ci,4))

